package com.jestk.browser.engine.adblock

import android.content.Context
import android.util.Log
import com.jestk.browser.engine.AdBlockerEngine
import com.jestk.browser.util.UrlSecurityUtils
import java.io.InputStream

/**
 * Hosts whose `$popup` filter rule opens no window (`assets/adblock_popup_hosts.txt`, generated by
 * `tools/build_adblock_list.py`). The native engine ignores `$popup`, so these are matched here.
 */
internal object PopupHostList {
    const val ASSET = "adblock_popup_hosts.txt"
    private const val TAG = "PopupHostList"

    private val hosts = HostBlocklist()

    @Volatile
    private var loadStarted = false

    /** Loads the asset once, on a background thread. */
    fun warm(context: Context) {
        if (loadStarted) return
        synchronized(this) {
            if (loadStarted) return
            loadStarted = true
        }
        val appContext = context.applicationContext ?: context
        Thread({
            try {
                appContext.assets.open(ASSET).use { load(it) }
            } catch (e: Exception) {
                Log.w(TAG, "Failed to load $ASSET", e)
            }
        }, "popup-host-list").start()
    }

    fun load(stream: InputStream) {
        stream.bufferedReader(Charsets.UTF_8).useLines { lines ->
            lines.map { it.trim() }
                .filter { it.isNotEmpty() && !it.startsWith("#") && !it.startsWith("!") }
                .forEach { hosts.add(it.lowercase()) }
        }
    }

    fun containsHostOf(url: String): Boolean {
        val host = UrlSecurityUtils.extractHost(url).lowercase()
        return host.isNotEmpty() && hosts.matchedSuffixStart(host) != -1
    }

    fun reset() {
        hosts.clear()
        loadStarted = false
    }
}

/** The ad check of [PopupGate]: a `DOCUMENT` match against the engines, or a `$popup` host. */
internal fun isAdPopupUrl(url: String): Boolean =
    AdBlockerEngine.shouldBlockNavigation(url) || PopupHostList.containsHostOf(url)
